icon_managed_marker_lines() {
  printf '%s\n' '# 由小克写入的同人图标,非Anthropic出品。用`clear`移除。'
  printf '%s\n' '# 由小克寫入的同人圖示,非Anthropic出品。用`clear`移除。'
